CREATE UNIQUE INDEX external_reputations_verified_identity_unique ON external_reputations(platform,profile_url) WHERE verification_status='VERIFIED';
CREATE TABLE reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_user_id uuid REFERENCES users(id),entity_type varchar(80) NOT NULL CHECK(entity_type='REVIEW'),entity_id uuid NOT NULL,reason_code varchar(80) NOT NULL,description text CHECK(description IS NULL OR char_length(description)<=2000),status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','RESOLVED','DISMISSED')),assigned_to_user_id uuid REFERENCES users(id),resolution text,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,UNIQUE(reporter_user_id,entity_type,entity_id,reason_code));
CREATE INDEX reports_status_created_idx ON reports(status,created_at);
CREATE INDEX reports_entity_created_idx ON reports(entity_type,entity_id,created_at DESC);
CREATE TABLE fraud_signals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),entity_type varchar(80),entity_id uuid,signal_type varchar(100) NOT NULL,severity smallint NOT NULL CHECK(severity BETWEEN 1 AND 5),evidence jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(evidence)='object'),status text NOT NULL DEFAULT 'OPEN',created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz);
CREATE INDEX fraud_signals_status_created_idx ON fraud_signals(status,created_at);
